def rle(s: str) -> str:
    """See SPEC.md."""
    out = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        out.append(s[i])
        out.append(str(j - i))
        i = j
    return "".join(out)

